export const GUIDE_HTML: string = "<!-- Generated from docs/SYSTEM-GUIDE-BN.md by scripts/build-admin-guide.mjs. Do not edit by hand. No secrets. -->\n<div class=\"guide-body\" lang=\"bn\">\n<h2>CPAY সিস্টেম গাইড (বাংলা)</h2>\n<p>এই গাইডে সহজ ভাষায় লেখা আছে CPAY চালাতে কোন কোন account লাগে, শুরু থেকে কীভাবে setup করবেন, Admin Settings-এর প্রতিটা জিনিস কী করে, কোন secret কোথায় থাকে, কোন API বা Edge Function কী করে, deploy-এর ক্রম, প্রতিদিন কী দেখবেন, আর সাধারণ সমস্যার সমাধান।</p>\n<p>এখানে কোনো secret-এর মান (value) নেই, শুধু নাম আছে। মান কখনো repo, chat বা ticket-এ রাখবেন না।</p>\n<p>Admin panel-এ <strong>সিস্টেম গাইড</strong> বাটনে এই একই লেখা দেখা যায়, কিন্তু <strong>শুধু owner</strong> (Edge secret <code>CPAY_OWNER_USER_ID</code>-এর account), passkey দিয়ে sign in করা থাকলে। অন্য admin বাটনই দেখে না। লেখাটা <code>owner-guide</code> Edge Function-এর ভেতরে থাকে, সাইটের কোনো public file-এ নয়। এই file বদলালে চালান: <code>node scripts/build-admin-guide.mjs</code>, তারপর <code>owner-guide</code> আবার deploy করুন।</p>\n<h3>সূচিপত্র</h3>\n<ol><li><a href=\"#guide-accounts\">কোন কোন account লাগে</a></li><li><a href=\"#guide-setup\">শুরু থেকে setup</a></li><li><a href=\"#guide-settings\">Admin Settings</a></li><li><a href=\"#guide-secrets\">Secret আর env var</a></li><li><a href=\"#guide-apis\">API আর Edge Function</a></li><li><a href=\"#guide-deploy\">Deploy-এর ক্রম আর প্রতিদিনের check</a></li><li><a href=\"#guide-problems\">সাধারণ সমস্যা আর সমাধান</a></li><li><a href=\"#guide-updates\">সাম্প্রতিক আপডেট</a></li><li><a href=\"#guide-todo\">এখন কী কী setting করতে হবে</a></li><li><a href=\"#guide-wallets\">একাধিক wallet</a></li><li><a href=\"#guide-btcpay\">BTCPay Server দিয়ে invoice</a></li></ol>\n<span id=\"guide-accounts\" class=\"guide-anchor\"></span>\n<h3>১. কোন কোন account লাগে</h3>\n<div class=\"scroll\"><table class=\"table rtable\"><thead><tr><th>Account</th><th>CPAY-তে কী কাজ</th><th>না থাকলে কী হয়</th><th>খরচ</th></tr></thead><tbody><tr><td data-label=\"Account\">GitHub (<code>parvezmosharafvu/cpay</code>)</td><td data-label=\"CPAY-তে কী কাজ\">Code রাখা, Pull Request, CI (<code>.github/workflows/verify.yml</code>), wallet deploy-এর আগে &quot;Verify&quot; সবুজ কিনা দেখা</td><td data-label=\"না থাকলে কী হয়\">Code বদলানো বা deploy করা যায় না; wallet deploy script নিজেই থেমে যায়</td><td data-label=\"খরচ\">Private repo-তে Actions-এর মাসিক ফ্রি মিনিট আছে</td></tr><tr><td data-label=\"Account\">GitHub ledger backup repo (private, আলাদা)</td><td data-label=\"CPAY-তে কী কাজ\"><code>ledger-backup</code> প্রতি রাতে হিসাবের snapshot এখানে commit করে</td><td data-label=\"না থাকলে কী হয়\">Backup হয় না, alert যায়</td><td data-label=\"খরচ\">ফ্রি</td></tr><tr><td data-label=\"Account\">Supabase (project <code>riumaeihemgznvgattoc</code>)</td><td data-label=\"CPAY-তে কী কাজ\">Database (Postgres), Auth (login), Edge Functions, secrets, Vault, pg_cron</td><td data-label=\"না থাকলে কী হয়\">পুরো সাইট বন্ধ: login, payment, withdraw কিছুই চলে না</td><td data-label=\"খরচ\">ফ্রি plan আছে; production-এ Pro plan রাখাই নিরাপদ (backup, pause হয় না)</td></tr><tr><td data-label=\"Account\">Cloudflare</td><td data-label=\"CPAY-তে কী কাজ\">Worker <code>cpay</code> (সাইট, <code>public/</code> folder, <code>wrangler.jsonc</code>), Worker <code>cpay-og-preview</code> (link preview আর invoice rate limit, <code>worker/wrangler.jsonc</code>), Workers Builds (main থেকে auto deploy), DNS, Turnstile (bot check)</td><td data-label=\"না থাকলে কী হয়\">সাইট খোলে না; Turnstile না থাকলে নতুন invoice আটকে যেতে পারে</td><td data-label=\"খরচ\">Workers আর Turnstile-এর ফ্রি plan যথেষ্ট</td></tr><tr><td data-label=\"Account\">Domain registrar (<code>pay-cashapp.buzz</code>)</td><td data-label=\"CPAY-তে কী কাজ\">Domain-এর মালিকানা; nameserver Cloudflare-এ দেওয়া</td><td data-label=\"না থাকলে কী হয়\">Domain মেয়াদ শেষ হলে সাইট আর email দুটোই বন্ধ</td><td data-label=\"খরচ\">বছরে একবার renew</td></tr><tr><td data-label=\"Account\">Wallet provider (API key)</td><td data-label=\"CPAY-তে কী কাজ\">Lightning invoice বানানো, payment পাওয়া, forward আর withdraw পাঠানো, USDT swap</td><td data-label=\"না থাকলে কী হয়\">কোনো payment আসে না, কিছু পাঠানো যায় না</td><td data-label=\"খরচ\">Provider-এর নিজের শর্ত</td></tr><tr><td data-label=\"Account\">Resend (email sender)</td><td data-label=\"CPAY-তে কী কাজ\">Supabase Auth-এর email (verification, password reset) <code>no-reply@pay-cashapp.buzz</code> থেকে SMTP দিয়ে পাঠায় (<code>docs/CPAY_AUTH_AND_EMAIL.md</code>)</td><td data-label=\"না থাকলে কী হয়\">নতুন user email verify করতে পারে না, password reset যায় না</td><td data-label=\"খরচ\">ফ্রি plan-এ দৈনিক সীমা আছে</td></tr><tr><td data-label=\"Account\">Telegram bot (@BotFather)</td><td data-label=\"CPAY-তে কী কাজ\">Settled payment-এর বার্তা আর ops alert admin group-এ (<code>telegram-notify</code>)</td><td data-label=\"না থাকলে কী হয়\">বার্তা queue-তে জমে থাকে, payment-এ কোনো সমস্যা হয় না</td><td data-label=\"খরচ\">ফ্রি</td></tr><tr><td data-label=\"Account\">Alert webhook (ঐচ্ছিক)</td><td data-label=\"CPAY-তে কী কাজ\"><code>ALERT_WEBHOOK_URL</code>: health fail, backup fail হলে বার্তা</td><td data-label=\"না থাকলে কী হয়\">Alert চুপচাপ বাদ যায়</td><td data-label=\"খরচ\">ফ্রি</td></tr></tbody></table></div>\n<p>আলাদা কোনো USDT/Tron server নেই। USDT পাঠানো wallet provider-এর swap দিয়েই হয়।</p>\n<p><code>payment-service/</code> folder-এর Node service এখন deploy করা নেই। এটা শুধু CI-তে test হয়, backup হিসেবে রাখা।</p>\n<span id=\"guide-setup\" class=\"guide-anchor\"></span>\n<h3>২. শুরু থেকে setup (ক্রম মেনে)</h3>\n<h4>২.১ Account খোলা</h4>\n<ol><li>GitHub account আর repo। আলাদা একটা private repo ledger backup-এর জন্য।</li><li>Supabase account, একটা project (region কাছাকাছি)।</li><li>Cloudflare account, domain-কে Cloudflare-এ যোগ করুন, registrar-এ Cloudflare-এর nameserver দিন।</li><li>Wallet provider-এর কাছ থেকে API key নিন। Wallet-এর ১২/২৪ শব্দ (mnemonic) offline-এ লিখে রাখুন।</li><li>Resend-এ domain verify করুন (DNS record Cloudflare-এ)।</li><li>Telegram-এ @BotFather দিয়ে bot বানান, admin group-এ যোগ করুন।</li></ol>\n<h4>২.২ Repo আর database</h4>\n<ol><li>Repo clone করুন। <code>public/config.example.js</code> দেখে <code>public/config.js</code>-এ <code>SUPABASE_URL</code> আর anon key দিন (এগুলো public, লুকানোর দরকার নেই)।</li><li>Supabase CLI দিয়ে link: <code>supabase link --project-ref &lt;ref&gt;</code>।</li><li>Migration চালান: <code>supabase db push</code>। Migration সবসময় ক্রম অনুযায়ী চলে। পুরনো migration file কখনো বদলাবেন না।</li></ol>\n<h4>২.৩ Secret বসানো</h4>\n<p>Supabase → Edge Functions → Secrets-এ <a href=\"#guide-secrets\">৪ নম্বর অংশের</a> list অনুযায়ী secret দিন। <code>CRON_SECRET</code>-এর একই মান Vault-এও <code>cpay_cron_secret</code> নামে রাখুন।</p>\n<h4>২.৪ Edge Function deploy</h4>\n<ol><li>সাধারণ function: <code>supabase functions deploy &lt;name&gt;</code>। <code>supabase/config.toml</code>-এ প্রতিটার <code>verify_jwt</code> ঠিক করা আছে, ওটা বদলাবেন না।</li><li>Wallet function: শুধু <code>scripts/</code> folder-এর wallet deploy script দিয়ে (<code>scripts/deploy-…-wallet.sh &lt;project-ref&gt;</code>)। Script দেখে নেয় HEAD = <code>origin/main</code> আর ওই commit-এ &quot;Verify&quot; সবুজ কিনা। এটা single instance (lease) চালায়।</li></ol>\n<h4>২.৫ সাইট</h4>\n<p>Cloudflare → Workers → <code>cpay</code> → Workers Builds-এ GitHub repo যোগ করুন, branch <code>main</code>। এরপর main-এ merge হলেই সাইট নিজে থেকে deploy হয়। <code>worker/</code> folder-এর <code>cpay-og-preview</code> আলাদাভাবে <code>wrangler deploy</code> দিয়ে।</p>\n<h4>২.৬ Login (Auth) setting</h4>\n<p>Supabase → Authentication-এ:</p>\n<ul><li><strong>Email confirm চালু</strong> (Confirm email)। Admin → Settings থেকেও বদলানো যায় (<code>auth-settings</code>)।</li><li><strong>Passkeys চালু।</strong> কখনো বন্ধ করবেন না, admin-এর কাজ passkey ছাড়া হয় না।</li><li><strong>Google provider বন্ধ।</strong></li><li><strong>TOTP (authenticator app):</strong> পুরোপুরি বন্ধ — নতুন যোগ বন্ধ (<code>enroll_enabled = false</code>), পুরনো code-ও আর চলে না (<code>verify_enabled = false</code>, ২১ অক্টোবর ২০২৬)। পুরনো factor মোছা হয়নি; <code>strong_session()</code> এখনো aal2 মানে, কিন্তু code দিয়ে আর aal2 পাওয়া যায় না।</li><li>SMTP: Resend-এর তথ্য, sender <code>no-reply@pay-cashapp.buzz</code>।</li><li>Site URL আর Redirect URLs-এ নিজের domain আর <code>/reset.html</code>।</li></ul>\n<h4>২.৭ প্রথম admin</h4>\n<p>নিজের account বানিয়ে email verify করুন, database-এ admin role দিন, তারপর <strong>দুটো passkey</strong> যোগ করুন (ফোন আর password manager)।</p>\n<span id=\"guide-settings\" class=\"guide-anchor\"></span>\n<h3>৩. Admin Settings — প্রতিটা জিনিস সহজ ভাষায়</h3>\n<p>Admin → Settings-এ যা আছে (<code>public/admin-platform-settings.js</code>, <code>public/admin-owner-settings.js</code>)। বদলাতে passkey sign-in লাগে, আর প্রতিটা বদল audit-এ লেখা থাকে।</p>\n<h4>Auto withdraw (সবার জন্য)</h4>\n<ul><li><strong>Turn on:</strong> fee কাটার পর প্রতিটা payment নিজে থেকেই user-এর save করা Lightning বা USDT address-এ চলে যায় (instant forward)।</li><li><strong>Turn off:</strong> টাকা user-এর balance-এ জমা থাকে। User নিজে Withdraw page থেকে তোলে।</li><li>ভেতরে এটা <code>payment_mode</code> setting (<code>instant_forward</code> বা <code>balance</code>)। <code>direct</code> mode-এ payer সরাসরি user-এর wallet-এ দেয়, CPAY টাকা পায় না, fee নেয় না।</li></ul>\n<h4>Auto withdraw (প্রতিটা profile)</h4>\n<p>Admin → Manage users → প্রতিটা row-এ: <strong>Default</strong> (উপরের global setting মানবে), <strong>On</strong>, বা <strong>Off</strong>। কাউকে Off করলে তার আটকে থাকা forward balance-এ চলে যায়।</p>\n<h4>Platform fee</h4>\n<p>প্রতিটা payment-এ CPAY-এর fee (%), Balance আর Instant forward mode-এ। Manage users-এ কারো নিজস্ব fee দিলে সেটাই খাটে।</p>\n<h4>Legal pages</h4>\n<p><code>legal_entity_name</code>, <code>legal_address</code>, <code>legal_effective_date</code> (YYYY-MM-DD), <code>legal_jurisdiction</code>, <code>legal_courts</code>, <code>legal_privacy_email</code>, <code>legal_support_email</code>। এগুলো Terms, Privacy আর Refund page-এ বসে।</p>\n<p>**Features → Publish the legal pages (<code>legal_published</code>):** সব legal field পূরণ না হলে চালু হয় না। বন্ধ থাকলে ওই page-গুলো খালি দেখায়।</p>\n<h4>Domains</h4>\n<p>সাইটের domain list (<code>site_domains</code>)। এখানে domain যোগ করলে ৫ মিনিটের মধ্যে function-গুলো ওই domain থেকে call নেয় (CORS)।</p>\n<h4>Secrets &amp; keys</h4>\n<p>Supabase আর Cloudflare Worker-এর secret-এর <strong>শুধু নাম</strong> দেখায়। মান একবার দেওয়া যায়, আর কখনো দেখানো হয় না। <code>SUPABASE_</code> দিয়ে শুরু নামগুলো সুরক্ষিত। এটা কাজ করতে <code>CPAY_SUPABASE_ACCESS_TOKEN</code> আর Cloudflare-এর <code>CPAY_CLOUDFLARE_*</code> লাগে।</p>\n<h4>Cloudflare → Always Use HTTPS</h4>\n<p>সব http request-কে https-এ পাঠায়। চালু রাখুন।</p>\n<h4>Advanced (লুকানো, সাধারণত বদলানোর দরকার নেই)</h4>\n<ul><li><strong>Instant forward:</strong> <code>instant_forward_no_address</code> (address না থাকলে: balance-এ রাখা, নাকি payment নেওয়া বন্ধ), <code>instant_forward_min_sat</code>, <code>instant_forward_max_usd</code>, <code>instant_forward_max_fee_pct</code>, <code>instant_forward_max_attempts</code>।</li><li><strong>পুরনো switch:</strong> <code>custodial_receive_enabled</code>, <code>custodial_new_links_enabled</code>, <code>custodial_withdraw_enabled</code>, <code>fee_billing_enabled</code> — এখন Auto withdraw-ই এগুলো ঠিক করে।</li><li><strong>Direct payments:</strong> <code>direct_pilot_user_ids</code>, <code>direct_provider_hosts</code>।</li><li><strong>Subscription fees:</strong> <code>fee_pilot_no_fee</code>, <code>fee_subscription_price_usd</code>, <code>fee_free_tier_usd</code>, <code>fee_grace_days</code>।</li><li><strong>Admin wallet limits:</strong> <code>admin_send_daily_cap_usd</code> (admin দিনে কত পাঠাতে পারে), <code>admin_send_allowed_destinations</code>।</li></ul>\n<h4>Turnstile (bot check)</h4>\n<p>এটা Admin Settings-এ নয়, secret দিয়ে চলে: <code>TURNSTILE_SECRET_KEY</code> + <code>TURNSTILE_MODE</code> (<code>monitor</code> = শুধু log, <code>enforce</code> = token ছাড়া invoice হবে না)। Site key <code>public/config.js</code>-এ (public)। <code>direct-invoice</code> নতুন invoice বানায় শুধু <code>enforce</code> হলে।</p>\n<span id=\"guide-secrets\" class=\"guide-anchor\"></span>\n<h3>৪. Secret আর env var (শুধু নাম)</h3>\n<p>বেশিরভাগ secret থাকে <strong>Supabase → Edge Functions → Secrets</strong>-এ (পুরো project-এর জন্য এক জায়গা)। Admin → Settings → Secrets &amp; keys থেকেও বদলানো যায়। পরিবর্তন করতে পারেন শুধু Supabase project-এর owner/admin, বা passkey-সহ CPAY admin।</p>\n<div class=\"scroll\"><table class=\"table rtable\"><thead><tr><th>নাম</th><th>কোথায়</th><th>কে ব্যবহার করে</th><th>না থাকলে</th></tr></thead><tbody><tr><td data-label=\"নাম\"><code>SUPABASE_URL</code>, <code>SUPABASE_ANON_KEY</code>, <code>SUPABASE_SERVICE_ROLE_KEY</code></td><td data-label=\"কোথায়\">Supabase নিজেই দেয়</td><td data-label=\"কে ব্যবহার করে\">সব function</td><td data-label=\"না থাকলে\">—</td></tr><tr><td data-label=\"নাম\"><code>BREEZ_MNEMONIC</code></td><td data-label=\"কোথায়\">Edge secret (wallet function)</td><td data-label=\"কে ব্যবহার করে\">Wallet</td><td data-label=\"না থাকলে\">Wallet চালু হয় না</td></tr><tr><td data-label=\"নাম\"><code>BREEZ_API_KEY</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\">Wallet (wallet provider key)</td><td data-label=\"না থাকলে\">Mainnet-এ wallet চলে না</td></tr><tr><td data-label=\"নাম\"><code>BREEZ_NETWORK</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\">Wallet (<code>mainnet</code>)</td><td data-label=\"না থাকলে\">Wallet চালু হয় না</td></tr><tr><td data-label=\"নাম\"><code>BREEZ_DB_URL</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\">Wallet-এর নিজের schema</td><td data-label=\"না থাকলে\">Wallet চালু হয় না</td></tr><tr><td data-label=\"নাম\"><code>PAYMENT_SERVICE_URL</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\"><code>create-invoice</code>, <code>user-withdraw</code>, <code>admin-actions</code>, <code>health</code></td><td data-label=\"না থাকলে\">Invoice আর withdraw বন্ধ</td></tr><tr><td data-label=\"নাম\"><code>PAYMENT_SERVICE_SECRET</code></td><td data-label=\"কোথায়\">Edge secret (দুই পাশে একই)</td><td data-label=\"কে ব্যবহার করে\">Function ↔ wallet</td><td data-label=\"না থাকলে\">Invoice বন্ধ</td></tr><tr><td data-label=\"নাম\"><code>PAYMENT_SERVICE_AUTH_MODE</code></td><td data-label=\"কোথায়\">Edge secret (ঐচ্ছিক)</td><td data-label=\"কে ব্যবহার করে\"><code>bearer</code> বা <code>signed</code></td><td data-label=\"না থাকলে\">Default <code>bearer</code></td></tr><tr><td data-label=\"নাম\"><code>ADMIN_JWT_MODE</code></td><td data-label=\"কোথায়\">Edge secret (ঐচ্ছিক)</td><td data-label=\"কে ব্যবহার করে\">Wallet-এর admin route</td><td data-label=\"না থাকলে\">Default</td></tr><tr><td data-label=\"নাম\"><code>CRON_SECRET</code></td><td data-label=\"কোথায়\">Edge secret + Vault <code>cpay_cron_secret</code></td><td data-label=\"কে ব্যবহার করে\">cron job, <code>health</code>, <code>daily-report</code>, <code>ledger-backup</code>, <code>telegram-notify</code>, wallet sync</td><td data-label=\"না থাকলে\">Scheduled কাজ সব বন্ধ</td></tr><tr><td data-label=\"নাম\"><code>STEP_UP_MAX_AGE_SECONDS</code></td><td data-label=\"কোথায়\">Edge secret (ঐচ্ছিক, 600)</td><td data-label=\"কে ব্যবহার করে\">Withdraw/admin confirm</td><td data-label=\"না থাকলে\">Default</td></tr><tr><td data-label=\"নাম\"><code>ADMIN_MFA_EXPECTED</code></td><td data-label=\"কোথায়\">Edge secret (ঐচ্ছিক)</td><td data-label=\"কে ব্যবহার করে\"><code>health</code></td><td data-label=\"না থাকলে\">Alert হয় না</td></tr><tr><td data-label=\"নাম\"><code>TURNSTILE_SECRET_KEY</code>, <code>TURNSTILE_MODE</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\"><code>create-invoice</code>, <code>direct-invoice</code></td><td data-label=\"না থাকলে\">Bot check বন্ধ; direct invoice বন্ধ</td></tr><tr><td data-label=\"নাম\"><code>ALLOWED_ORIGINS</code></td><td data-label=\"কোথায়\">Edge secret (ঐচ্ছিক)</td><td data-label=\"কে ব্যবহার করে\">CORS</td><td data-label=\"না থাকলে\">Domains list-ই যথেষ্ট</td></tr><tr><td data-label=\"নাম\"><code>ALERT_TELEGRAM_BOT_TOKEN</code>, <code>ALERT_TELEGRAM_CHAT_ID</code>, <code>ALERT_ON_SETTLED</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\"><code>telegram-notify</code>, alert</td><td data-label=\"না থাকলে\">বার্তা queue-তে জমে</td></tr><tr><td data-label=\"নাম\"><code>ALERT_WEBHOOK_URL</code></td><td data-label=\"কোথায়\">Edge secret (ঐচ্ছিক)</td><td data-label=\"কে ব্যবহার করে\">Alert</td><td data-label=\"না থাকলে\">Alert বাদ যায়</td></tr><tr><td data-label=\"নাম\"><code>CPAY_OWNER_USER_ID</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\"><code>owner-guide</code> (owner-এর Supabase Auth user id)</td><td data-label=\"না থাকলে\">System guide কেউ দেখতে পায় না</td></tr><tr><td data-label=\"নাম\"><code>GITHUB_TOKEN</code>, <code>GITHUB_OWNER</code>, <code>GITHUB_REPO</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\"><code>ledger-backup</code></td><td data-label=\"না থাকলে\">Backup হয় না</td></tr><tr><td data-label=\"নাম\"><code>CPAY_SUPABASE_ACCESS_TOKEN</code>, <code>CPAY_PROJECT_REF</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\"><code>auth-settings</code>, <code>owner-config</code></td><td data-label=\"না থাকলে\">Settings-এ &quot;Not set up&quot;</td></tr><tr><td data-label=\"নাম\"><code>CPAY_CLOUDFLARE_API_TOKEN</code>, <code>CPAY_CLOUDFLARE_ACCOUNT_ID</code>, <code>CPAY_CLOUDFLARE_ZONE_ID</code>, <code>CPAY_CLOUDFLARE_WORKER</code></td><td data-label=\"কোথায়\">Edge secret</td><td data-label=\"কে ব্যবহার করে\"><code>owner-config</code> (Worker secret, HTTPS)</td><td data-label=\"না থাকলে\">Cloudflare অংশ &quot;Not set up&quot;</td></tr><tr><td data-label=\"নাম\"><code>DIRECT_RECONCILE_SECRET</code>, <code>DIRECT_SETTLEMENT_NETWORK</code>, <code>DIRECT_PROVIDER_HOSTS</code></td><td data-label=\"কোথায়\">Edge secret (ঐচ্ছিক)</td><td data-label=\"কে ব্যবহার করে\"><code>direct-invoice</code>, <code>settlement-destination</code></td><td data-label=\"না থাকলে\">Direct-এর sweep বন্ধ</td></tr><tr><td data-label=\"নাম\"><code>CPAY_BASE_URL</code>, <code>CPAY_ADMIN_EMAIL</code>, <code>CPAY_ADMIN_PASSWORD</code></td><td data-label=\"কোথায়\">GitHub → Settings → Secrets → Actions</td><td data-label=\"কে ব্যবহার করে\"><code>e2e.yml</code> (live admin smoke test)</td><td data-label=\"না থাকলে\">ওই test skip/fail</td></tr><tr><td data-label=\"নাম\"><code>CPAY_TURNSTILE_SITE_KEY</code>, Supabase URL, anon key</td><td data-label=\"কোথায়\"><code>public/config.js</code> (public)</td><td data-label=\"কে ব্যবহার করে\">Browser</td><td data-label=\"না থাকলে\">Login/invoice কাজ করে না</td></tr></tbody></table></div>\n<p>খুব শক্তিশালী token: <code>CPAY_SUPABASE_ACCESS_TOKEN</code> (পুরো Supabase account-এ কাজ করে) আর <code>BREEZ_MNEMONIC</code> (wallet-এর সব টাকা)। এগুলো শুধু Edge secret-এ রাখুন।</p>\n<h4>কীভাবে rotate করবেন</h4>\n<ol><li>নতুন মান বানান (যেমন <code>openssl rand -hex 32</code>), বা provider-এর dashboard থেকে নতুন key নিন।</li><li>Supabase → Edge Functions → Secrets-এ (বা Admin → Settings → Secrets &amp; keys → Replace) নতুন মান দিন। Function নিজে থেকেই নতুন মান নেয়।</li><li><code>CRON_SECRET</code> বদলালে SQL editor-এ Vault-এও একই মান দিন: <code>select vault.create_secret('&lt;নতুন মান&gt;', 'cpay_cron_secret');</code></li><li><code>PAYMENT_SERVICE_SECRET</code> দুই পাশে একসাথে বদলান।</li><li>পুরনো key provider-এর dashboard থেকে revoke করুন।</li><li>Admin → Health দেখে নিন সব সবুজ।</li><li><code>BREEZ_MNEMONIC</code> &quot;rotate&quot; করা যায় না, এটা wallet নিজেই; বদলানো মানে নতুন wallet আর টাকা সরানো — আগে পরিকল্পনা করুন।</li></ol>\n<span id=\"guide-apis\" class=\"guide-anchor\"></span>\n<h3>৫. API আর Edge Function</h3>\n<div class=\"scroll\"><table class=\"table rtable\"><thead><tr><th>Function</th><th>কী করে</th><th>কে call করে</th></tr></thead><tbody><tr><td data-label=\"Function\"><code>create-invoice</code></td><td data-label=\"কী করে\">Payment link থেকে USD amount নিয়ে Lightning invoice বানায়</td><td data-label=\"কে call করে\">Payer-এর browser (checkout), Worker-এর <code>/api/create-invoice</code></td></tr><tr><td data-label=\"Function\"><code>direct-invoice</code></td><td data-label=\"কী করে\">Direct mode-এ user-এর নিজের wallet থেকে invoice</td><td data-label=\"কে call করে\">Payer-এর browser; reconcile sweep</td></tr><tr><td data-label=\"Function\"><code>user-withdraw</code></td><td data-label=\"কী করে\">Manual withdraw (passkey confirm)</td><td data-label=\"কে call করে\">Signed-in user (Withdraw page)</td></tr><tr><td data-label=\"Function\"><code>settlement-destination</code></td><td data-label=\"কী করে\">User-এর payout address save/check</td><td data-label=\"কে call করে\">Signed-in user</td></tr><tr><td data-label=\"Function\"><code>admin-actions</code></td><td data-label=\"কী করে\">Admin-এর wallet আর payout কাজ</td><td data-label=\"কে call করে\">Admin panel</td></tr><tr><td data-label=\"Function\"><code>auth-settings</code></td><td data-label=\"কী করে\">Email confirm চালু/বন্ধ</td><td data-label=\"কে call করে\">Admin panel</td></tr><tr><td data-label=\"Function\"><code>owner-config</code></td><td data-label=\"কী করে\">Secret-এর নাম দেখা/বসানো, Cloudflare HTTPS</td><td data-label=\"কে call করে\">Admin panel</td></tr><tr><td data-label=\"Function\">Wallet function</td><td data-label=\"কী করে\">Wallet চালায়: receive, forward, withdraw, sync</td><td data-label=\"কে call করে\">অন্য function আর cron (<code>PAYMENT_SERVICE_SECRET</code> দিয়ে)</td></tr><tr><td data-label=\"Function\"><code>health</code></td><td data-label=\"কী করে\">সিস্টেম ঠিক আছে কিনা দেখে, alert দেয়</td><td data-label=\"কে call করে\">cron, Admin → Health</td></tr><tr><td data-label=\"Function\"><code>daily-report</code></td><td data-label=\"কী করে\">দৈনিক হিসাব বন্ধ করা</td><td data-label=\"কে call করে\">cron</td></tr><tr><td data-label=\"Function\"><code>ledger-backup</code></td><td data-label=\"কী করে\">রাতের backup GitHub-এ</td><td data-label=\"কে call করে\">cron</td></tr><tr><td data-label=\"Function\"><code>telegram-notify</code></td><td data-label=\"কী করে\">Queue থেকে Telegram বার্তা পাঠায়</td><td data-label=\"কে call করে\">cron</td></tr><tr><td data-label=\"Function\"><code>og-image</code></td><td data-label=\"কী করে\">Link preview-এর ছবি</td><td data-label=\"কে call করে\"><code>cpay-og-preview</code> Worker</td></tr><tr><td data-label=\"Function\"><code>owner-guide</code></td><td data-label=\"কী করে\">এই গাইড শুধু owner-কে দেয় (passkey session লাগে)</td><td data-label=\"কে call করে\">Admin → System guide</td></tr><tr><td data-label=\"Function\"><code>wallet-registry</code></td><td data-label=\"কী করে\">একাধিক wallet: তালিকা, seed দিয়ে নতুন wallet যোগ, primary করা, নাম বদলানো, বন্ধ, সরানো (শুধু owner, passkey)</td><td data-label=\"কে call করে\">Admin → Wallet → Wallets</td></tr></tbody></table></div>\n<p>এছাড়া database-এর RPC (যেমন <code>admin_platform_settings</code>, <code>admin_set_platform_setting</code>, <code>admin_set_auto_withdraw_global</code>, <code>admin_locations</code>) admin panel সরাসরি call করে। সব admin RPC active admin আর passkey session চায়।</p>\n<p>Cron job (<code>pg_cron</code>): wallet sync, <code>cpay-daily-close</code>, <code>cpay-telegram-send</code>, <code>prune-webhook-events</code>, <code>receipt-review-sweep</code>।</p>\n<span id=\"guide-deploy\" class=\"guide-anchor\"></span>\n<h3>৬. Deploy-এর ক্রম আর প্রতিদিনের check</h3>\n<h4>Deploy-এর ক্রম</h4>\n<ol><li>Migration (নতুন file, main-এর সব migration-এর পরে sort হয়)।</li><li>Edge Function: <code>supabase functions deploy &lt;name&gt;</code>; wallet শুধু wallet deploy script দিয়ে। গাইড বদলালে <code>supabase functions deploy owner-guide</code> (প্রথমবার আগে <code>CPAY_OWNER_USER_ID</code> secret দিন)।</li><li>সাইট: main-এ merge হলে Cloudflare Workers Builds নিজে deploy করে।</li></ol>\n<p>উল্টো ক্রমে করলে নতুন code পুরনো database খুঁজে না পেয়ে fail করতে পারে।</p>\n<h4>প্রতিদিন যা দেখবেন</h4>\n<ul><li>Admin → Health: সব সবুজ কিনা, wallet lease চলছে কিনা।</li><li>Admin → Instant forwards: আটকে থাকা (held/owed) forward আছে কিনা।</li><li>Admin → Payouts: failed withdraw।</li><li>Telegram group-এ alert এসেছে কিনা।</li><li>GitHub-এ main-এর check সবুজ কিনা।</li><li>সপ্তাহে একবার: ledger backup repo-তে নতুন commit, Resend-এ bounce।</li><li>মাসে একবার: domain আর token-এর মেয়াদ।</li></ul>\n<span id=\"guide-problems\" class=\"guide-anchor\"></span>\n<h3>৭. সাধারণ সমস্যা আর সমাধান</h3>\n<div class=\"scroll\"><table class=\"table rtable\"><thead><tr><th>সমস্যা</th><th>সম্ভাব্য কারণ</th><th>কী করবেন</th></tr></thead><tbody><tr><td data-label=\"সমস্যা\">Invoice বানাতে 503</td><td data-label=\"সম্ভাব্য কারণ\">Wallet বন্ধ, বা <code>PAYMENT_SERVICE_*</code> ভুল</td><td data-label=\"কী করবেন\">Admin → Health দেখুন; secret মিলিয়ে দেখুন; wallet আবার deploy</td></tr><tr><td data-label=\"সমস্যা\">Invoice-এ &quot;captcha&quot; error</td><td data-label=\"সম্ভাব্য কারণ\">Turnstile site key আর secret মেলে না</td><td data-label=\"কী করবেন\"><code>TURNSTILE_MODE=monitor</code> করে দেখুন, key মিলিয়ে নিন</td></tr><tr><td data-label=\"সমস্যা\">Forward আটকে আছে</td><td data-label=\"সম্ভাব্য কারণ\">User-এর address কাজ করছে না</td><td data-label=\"কী করবেন\">User-কে address ঠিক করতে বলুন; বা ওই profile-এ Auto withdraw Off করুন (টাকা balance-এ যাবে)</td></tr><tr><td data-label=\"সমস্যা\">Withdraw &quot;reauth_required&quot;</td><td data-label=\"সম্ভাব্য কারণ\">Passkey sign-in পুরনো</td><td data-label=\"কী করবেন\">আবার passkey দিয়ে sign in</td></tr><tr><td data-label=\"সমস্যা\">Verification email আসে না</td><td data-label=\"সম্ভাব্য কারণ\">Resend/SMTP ভুল বা দৈনিক সীমা শেষ</td><td data-label=\"কী করবেন\">Resend log আর Supabase Auth → SMTP দেখুন</td></tr><tr><td data-label=\"সমস্যা\">Cron চলছে না</td><td data-label=\"সম্ভাব্য কারণ\"><code>CRON_SECRET</code> আর Vault-এর মান আলাদা</td><td data-label=\"কী করবেন\">দুটো একই মান দিন</td></tr><tr><td data-label=\"সমস্যা\">Telegram বার্তা নেই</td><td data-label=\"সম্ভাব্য কারণ\">Bot token নেই বা bot group-এ নেই</td><td data-label=\"কী করবেন\"><code>ALERT_TELEGRAM_*</code> দেখুন</td></tr><tr><td data-label=\"সমস্যা\">Settings-এ &quot;Not set up&quot;</td><td data-label=\"সম্ভাব্য কারণ\"><code>CPAY_SUPABASE_ACCESS_TOKEN</code> বা <code>CPAY_CLOUDFLARE_*</code> নেই</td><td data-label=\"কী করবেন\">Supabase-এ secret দিন</td></tr><tr><td data-label=\"সমস্যা\">Legal page খালি</td><td data-label=\"সম্ভাব্য কারণ\"><code>legal_published</code> বন্ধ</td><td data-label=\"কী করবেন\">Legal field পূরণ করে চালু করুন</td></tr><tr><td data-label=\"সমস্যা\">&quot;Supabase Preview&quot; check লাল</td><td data-label=\"সম্ভাব্য কারণ\">DB-এর migration history আর repo-র file মেলে না</td><td data-label=\"কী করবেন\">Read-only ভাবে <code>supabase_migrations.schema_migrations</code> আর <code>supabase/migrations/</code> মিলিয়ে দেখুন; history হাতে বদলাবেন না</td></tr><tr><td data-label=\"সমস্যা\">Admin-এ ঢুকতে পারছেন না</td><td data-label=\"সম্ভাব্য কারণ\">Passkey হারিয়েছে</td><td data-label=\"কী করবেন\">দ্বিতীয় passkey ব্যবহার করুন; তাই সবসময় দুটো রাখুন</td></tr></tbody></table></div>\n<span id=\"guide-updates\" class=\"guide-anchor\"></span>\n<h3>৮. সাম্প্রতিক আপডেট</h3>\n<p>Merge commit <code>git log</code> থেকে মিলিয়ে লেখা।</p>\n<div class=\"scroll\"><table class=\"table rtable\"><thead><tr><th>তারিখ</th><th>কী এসেছে</th><th>PR / merge commit</th></tr></thead><tbody><tr><td data-label=\"তারিখ\">২০ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>Instant forward:</strong> fee কাটার পর টাকা সরাসরি user-এর নিজের Lightning বা USDT address-এ যায়; না গেলে held/owed হয়ে আবার চেষ্টা হয়</td><td data-label=\"PR / merge commit\">#132–#136 (<code>473043a</code>, <code>f564af9</code>, <code>59b51aa</code>, <code>8193733</code>), USDT forward #139/#140 (<code>e0b12f1</code>, <code>47460e2</code>), safety fix #142 (<code>078fa7d</code>), শুধু instant mode #147 (<code>be4661e</code>)</td></tr><tr><td data-label=\"তারিখ\">২০ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>একটাই &quot;You receive&quot; amount:</strong> user শুধু একটা সংখ্যা দেখে, কত পাবে</td><td data-label=\"PR / merge commit\">#141 (<code>6017ad5</code>)</td></tr><tr><td data-label=\"তারিখ\">২০ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>Address সাথে সাথে বদলায়</strong> (২৪ ঘণ্টার অপেক্ষা নেই)</td><td data-label=\"PR / merge commit\">#137 (<code>be72627</code>), #138 (<code>4be21d6</code>)</td></tr><tr><td data-label=\"তারিখ\">২০ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>নতুন এক-page checkout, নতুন dashboard আর location</strong> (payer-এর দেশ/অঞ্চল/শহর, শুধু দেখার জন্য)</td><td data-label=\"PR / merge commit\">#143 (<code>fd92d6a</code>), bangla #144/#145 (<code>4037045</code>, <code>0fee063</code>), theme preview #149 (<code>e77d788</code>)</td></tr><tr><td data-label=\"তারিখ\">২০ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\">Legal page-এর লেখা code-এর সাথে মেলানো</td><td data-label=\"PR / merge commit\">#146 (<code>4250afd</code>)</td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>Auto withdraw</strong> global switch + প্রতিটা profile-এ Default/On/Off, আর আলাদা <strong>manual Withdraw</strong> page</td><td data-label=\"PR / merge commit\">#151 (<code>885dff9</code>)</td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>Login শুধু passkey + email verification:</strong> Google বন্ধ, নতুন authenticator (TOTP) যোগ বন্ধ, admin কাজে passkey লাগে</td><td data-label=\"PR / merge commit\">#152 (<code>0d634e5</code>)</td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\">Repo পরিষ্কার, <code>AGENTS.md</code> আর <code>docs/SYSTEM-OVERVIEW.md</code></td><td data-label=\"PR / merge commit\">#153 (<code>ce32488</code>)</td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>দিনের হিসাব এখন বাংলাদেশের দিন:</strong> রাত ১২টা থেকে রাত ১২টা (Asia/Dhaka), আগে ছিল বিকেল ৫টা থেকে ৫টা। Dashboard, admin daily stats, দৈনিক withdraw limit, Telegram report সব একসাথে। আগের দিনগুলোর হিসাব আগের নিয়মেই থাকে</td><td data-label=\"PR / merge commit\">#156 (<code>5c62118</code>), migration <code>20261021030000_dhaka_calendar_day</code></td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>Authenticator code পুরোপুরি বন্ধ</strong> (TOTP যোগ আর ব্যবহার দুটোই off, passkey login আগের মতো); repo-তে কোথাও ব্যবহার না হওয়া একটা অজানা পুরনো Edge secret মোছা</td><td data-label=\"PR / merge commit\">Supabase dashboard setting (code বদল নেই)</td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>এই System guide</strong>, শুধু owner দেখতে পারেন (<code>owner-guide</code> function)</td><td data-label=\"PR / merge commit\">#154</td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>একাধিক wallet:</strong> Admin → Wallet-এ ১২ শব্দের seed paste করে নতুন wallet যোগ; seed Supabase Vault-এ encrypted; একটা primary wallet নতুন invoice, forward আর withdraw চালায়; বাকিগুলো প্রতি মিনিটে শুধু টাকা আসা দেখে। যোগ করতে: Admin → <strong>Wallet</strong> → <strong>Add a wallet</strong> → নাম + ১২ শব্দ → passkey দিয়ে confirm; ১-২ মিনিটে balance দেখাবে। বর্তমান wallet Wallet #1 হিসেবে primary (১০ দেখুন)</td><td data-label=\"PR / merge commit\">#157 (<code>c1dd66d</code>), migration <code>20261021040000_multi_wallet</code></td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>Google পুরোপুরি সরানো:</strong> repo থেকে Google login-এর বাকি code, test mock আর লেখা বাদ; Supabase-এ Google provider বন্ধ। Client id/secret মোছা আর admin account থেকে Google identity আলাদা করা dashboard-এ বাকি (৯.৫ দেখুন)</td><td data-label=\"PR / merge commit\">#155</td></tr><tr><td data-label=\"তারিখ\">২১ অক্টোবর ২০২৬</td><td data-label=\"কী এসেছে\"><strong>Health পেজ ঠিক:</strong> payment check-এ আগে &quot;last synced undefined&quot; দেখাত; এখন primary wallet শেষ কখন sync হয়েছে তা বাংলাদেশ সময়ে দেখায় (যেমন <code>Wallet 1 last synced 2026-10-21 05:47 (Dhaka), 1 min ago</code>)</td><td data-label=\"PR / merge commit\">fix/health-last-synced</td></tr></tbody></table></div>\n<span id=\"guide-todo\" class=\"guide-anchor\"></span>\n<h3>৯. এখন কী কী setting করতে হবে</h3>\n<p>২১ অক্টোবর ২০২৬, ভোর ৪টা (ঢাকা) পর্যন্ত live অবস্থা শুধু পড়ে দেখা হয়েছে (কিছু বদলানো হয়নি)। ✅ = হয়ে গেছে, ⬜ = বাকি, ❔ = repo থেকে দেখা যায় না, আপনি dashboard-এ দেখে নিন।</p>\n<h4>৯.১ Auto withdraw</h4>\n<ul><li>✅ <strong>সবার জন্য On</strong> (এখন <code>payment_mode = instant_forward</code>)। বদলাতে: Admin → Settings → Auto withdraw → <strong>Turn on</strong> / <strong>Turn off</strong> → confirm।</li><li>⬜ <strong>কোনো একজনের জন্য আলাদা</strong> (ঐচ্ছিক): Admin → Manage users → ওই user-এর row → Auto withdraw → <strong>Default / On / Off</strong>। Off করলে তার টাকা balance-এ জমবে, সে Withdraw page থেকে তুলবে।</li><li>✅ <strong>Address না থাকলে:</strong> এখন <code>refuse</code> — যার address নেই সে payment নিতে পারে না। বদলাতে: Settings → Advanced → Instant forward → <code>instant_forward_no_address</code>।</li></ul>\n<h4>৯.২ Fee আর limit</h4>\n<ul><li>✅ <strong>Platform fee 5%।</strong> বদলাতে: Settings → Platform fee → নতুন % → <strong>Save fee</strong>। কারো আলাদা fee: Manage users → ওই row।</li><li>✅ Forward limit (<code>instant_forward_min_sat</code>, <code>instant_forward_max_usd</code>, <code>instant_forward_max_fee_pct</code>, <code>instant_forward_max_attempts</code>) — default মান চলছে। দরকার হলে Settings → Advanced → Instant forward।</li><li>⬜ <strong>Hot-wallet cap:</strong> <code>admin_send_daily_cap_usd</code> এখনো দেওয়া নেই। Settings → Advanced → Admin wallet limits → একটা দৈনিক সীমা (USD) দিন, আর <code>admin_send_allowed_destinations</code>-এ নিজের address দিন।</li></ul>\n<h4>৯.৩ Legal</h4>\n<ul><li>⬜ <strong>Legal field (আপনি নিজে পরে পূরণ করবেন):</strong> সব খালি। Settings → Legal pages → entity name, address, effective date (YYYY-MM-DD), jurisdiction, courts, privacy email, support email → প্রতিটা <strong>Save</strong>।</li><li>⬜ <strong>Publish:</strong> তারপর Settings → Features → <strong>Publish the legal pages</strong> চালু (<code>legal_published</code>)।</li></ul>\n<h4>৯.৪ Secret</h4>\n<ul><li>❔ **<code>TURNSTILE_MODE=enforce</code>:** secret আছে (শেষ বদল ১৫ অক্টোবর), কিন্তু মান পড়া যায় না। Supabase → Edge Functions → Secrets বা Admin → Settings → Secrets &amp; keys → <code>TURNSTILE_MODE</code> → Replace → <code>enforce</code>। আগে দেখুন checkout-এ Turnstile ঠিক চলছে।</li><li>⬜ **<code>DIRECT_RECONCILE_SECRET</code>:** দেওয়া নেই। Direct payment চালু করলে লাগবে: <code>openssl rand -hex 32</code> দিয়ে বানিয়ে Secrets-এ দিন।</li><li>⬜ **Wallet provider key rotate (<code>BREEZ_API_KEY</code>):** শেষ বদল ১২ অক্টোবর। Provider-এর dashboard থেকে নতুন key নিন → Supabase dashboard → Edge Functions → Secrets → <code>BREEZ_API_KEY</code> বদলান (Admin panel থেকে বদলানো যায় না, এটা সুরক্ষিত) → wallet function আবার deploy (wallet deploy script) → Admin → Health সবুজ কিনা দেখুন → পুরনো key revoke।</li><li>⬜ <strong>পুরনো Telegram bot revoke:</strong> @BotFather → <code>/mybots</code> → পুরনো bot → API Token → <strong>Revoke</strong>। নতুন token <code>ALERT_TELEGRAM_BOT_TOKEN</code>-এ আছে (শেষ বদল ৭ অক্টোবর); revoke-এর পর একটা test বার্তা আসে কিনা দেখুন।</li><li>✅ **<code>CPAY_OWNER_USER_ID</code>:** owner-এর account-এর id দেওয়া হয়েছে (System guide-এর জন্য)।</li></ul>\n<h4>৯.৫ Backup আর login</h4>\n<ul><li>❔ <strong>Supabase PITR (Point-in-time recovery):</strong> Supabase → Project Settings → Add-ons → Point in time recovery চালু আছে কিনা দেখুন (paid add-on)।</li><li>✅ <strong>পুরনো authenticator code বন্ধ:</strong> আপনি passkey দিয়ে admin login নিশ্চিত করার পর ২১ অক্টোবর ২০২৬ ভোর ৫টায় (ঢাকা) Supabase Auth-এ TOTP verify বন্ধ করা হয়েছে। Factor মোছা হয়নি।</li><li>✅ Google login বন্ধ (provider off), repo থেকে সব Google code সরানো।</li><li>⬜ <strong>Google client id/secret মোছা:</strong> Supabase → Authentication → Sign In / Providers → Google → <strong>Client IDs</strong> আর <strong>Client Secret</strong> খালি করুন → Save (provider off-ই থাকবে)। CLI এই দুটো field push করে না, তাই হাতে করতে হবে। তারপর Google Cloud Console → APIs &amp; Services → Credentials → CPAY-এর OAuth client → <strong>Delete</strong>।</li><li>⬜ <strong>Admin account থেকে Google identity আলাদা করা:</strong> account-এ এখনো <code>email</code> আর <code>google</code> দুটো identity আছে (password আর passkey আছে, তাই আটকে যাওয়ার ভয় নেই)। Supabase-এ অন্য user-এর identity মোছার কোনো admin API বা dashboard বাটন নেই। আপনি অনুমতি দিলে SQL editor-এ একটাই লাইন: <code>delete from auth.identities where provider = 'google' and user_id = '&lt;আপনার user id&gt;';</code> (Authentication → Users → আপনার account থেকে user id দেখে নিন)।</li></ul>\n<h4>৯.৬ Real টাকা দিয়ে test (আপনি করবেন)</h4>\n<ul><li>⬜ Auto withdraw On profile-এ ছোট payment ($1–2): fee কেটে বাকিটা save করা address-এ যায় কিনা।</li><li>⬜ একটা profile Off করে payment: টাকা balance-এ জমে কিনা।</li><li>⬜ Off profile থেকে Withdraw: Lightning আর USDT, passkey দিয়ে confirm; History আর Admin → Payouts-এ দেখা যায় কিনা।</li><li>⬜ ইচ্ছে করে ভুল invoice দিয়ে withdraw: fail হলে টাকা balance-এ ফেরত আসে কিনা।</li><li>⬜ Address বদলানো (passkey দিয়ে): সাথে সাথে নতুন address-এ forward যায় কিনা।</li></ul>\n<span id=\"guide-wallets\" class=\"guide-anchor\"></span>\n<h3>১০. একাধিক wallet</h3>\n<p>Admin → <strong>Wallet</strong> খুললে সবার উপরে <strong>Wallets</strong> কার্ড দেখাবে, শুধু আপনার (owner) account-এ, passkey দিয়ে sign in করা থাকলে। অন্য admin এটা দেখে না।</p>\n<h4>কীভাবে কাজ করে</h4>\n<ul><li><strong>Wallet 1</strong> হলো আগের wallet। এর seed আগের মতোই Edge secret <code>BREEZ_MNEMONIC</code>-এ থাকে। Migration-এর পরে এটাই primary থাকে, তাই কিছুই বদলায় না।</li><li><strong>নতুন wallet:</strong> ১২ শব্দের seed paste করলে সেটা Supabase <strong>Vault</strong>-এ encrypted হয়ে থাকে। Database-এর কোনো সাধারণ column-এ থাকে না, আর কোনো page, log বা audit-এ কখনো দেখায় না। তালিকায় শুধু <strong>fingerprint</strong> (৮ অক্ষর) আর প্রথম sync-এর পরে <strong>node key</strong> দেখায়।</li><li><strong>Primary wallet:</strong> নতুন সব invoice এই wallet বানায়। Forward আর withdraw-ও এই wallet থেকেই যায়। একসাথে একটাই primary থাকে।</li><li><strong>অন্য active wallet:</strong> প্রতি মিনিটে শুধু দেখা হয় টাকা এসেছে কিনা। এতে আগের primary-র পুরনো invoice-এর payment-ও settle হয়, আর balance দেখায়। এগুলো থেকে কোনো টাকা পাঠানো হয় না।</li><li><strong>Standby:</strong> sync হয় না, ব্যবহারও হয় না। <strong>Disabled:</strong> একেবারে খোলা হয় না।</li><li>প্রতিটা wallet-এর আলাদা lease থাকে, তাই একই wallet কখনো একসাথে দুই জায়গায় চলে না।</li><li>প্রতিটা payment, forward আর withdraw-এ <code>wallet_id</code> লেখা থাকে। পুরনো row-এ এটা খালি থাকে, যার মানে Wallet 1।</li><li>সব wallet একই <code>BREEZ_API_KEY</code> ব্যবহার করে।</li></ul>\n<h4>দ্বিতীয় wallet যোগ করার ধাপ</h4>\n<ol><li>Admin-এ passkey দিয়ে sign in করুন, তারপর বাঁ দিকে <strong>Wallet</strong>-এ যান।</li><li><strong>Wallets</strong> কার্ডের নিচে <strong>Add a wallet</strong>-এ যান। <strong>Name</strong>-এ একটা নাম দিন, যেমন <code>Wallet 2</code>।</li><li><strong>12-word seed</strong> ঘরে ১২টা শব্দ paste করুন, মাঝে space রেখে। ঘরে লেখা লুকানো থাকে। নিচে <strong>Valid 12-word seed</strong> দেখালে বুঝবেন seed ঠিক আছে।</li><li><strong>Add wallet</strong> চাপুন, তারপর passkey দিয়ে নিশ্চিত করুন। ঘরটা সাথে সাথে খালি হয়ে যায়। সফল হলে fingerprint দেখাবে।</li><li>এক-দুই মিনিট অপেক্ষা করুন। cron প্রথম sync করলে balance, <strong>Synced</strong> সময় আর node key দেখাবে।</li><li>এই wallet দিয়ে নতুন invoice চালাতে চাইলে <strong>Make primary</strong> চাপুন। আগের primary নিজে থেকেই active থাকে, আর তার পুরনো invoice-এর টাকাও আসবে।</li></ol>\n<p><strong>মনে রাখবেন:</strong></p>\n<ul><li>ঘণ্টায় সর্বোচ্চ ৫ বার যোগ করার চেষ্টা করা যায়। ভুল চেষ্টাও এর মধ্যে গোনা হয়।</li><li>একই seed দুবার যোগ করা যায় না।</li><li>Seed-এর নিজের backup কাগজে রাখুন। Server থেকে seed আর কখনো দেখা যাবে না।</li></ul>\n<h4>সরানো (Remove)</h4>\n<p><strong>Remove</strong> চাপলে wallet-এর নাম হুবহু টাইপ করতে হবে, তারপর passkey লাগবে। নিচের যেকোনো একটা থাকলে server সরাতে দেবে না:</p>\n<ul><li>wallet-টা primary;</li><li>এটা Wallet 1 (এর seed Edge secret-এ থাকে);</li><li>balance ০-এর বেশি, বা গত ১৫ মিনিটে sync হয়নি;</li><li>খোলা invoice আছে;</li><li>forward বা withdraw চলছে।</li></ul>\n<p>সরালে Vault থেকে seed মুছে যায়। Row-টা &quot;removed&quot; হিসেবে থেকে যায়, যাতে পুরনো payment-এ wallet-এর নাম দেখা যায়।</p>\n<h4>Deploy-এর ক্রম (এই feature)</h4>\n<ol><li>Migration <code>20261021040000_multi_wallet.sql</code> চালান।</li><li><code>supabase functions deploy wallet-registry</code> (এর জন্য <code>CPAY_OWNER_USER_ID</code> আর <code>BREEZ_NETWORK</code> secret লাগে, দুটোই আগে থেকে আছে)।</li><li>Wallet function শুধু wallet deploy script দিয়ে deploy করুন।</li><li>সাইট (main-এ merge হলে নিজে থেকেই হয়)।</li></ol>\n<span id=\"guide-btcpay\" class=\"guide-anchor\"></span>\n<h3>১১. BTCPay Server দিয়ে invoice</h3>\n<p>Admin → <strong>Settings</strong> → <strong>BTCPay Server</strong> চালু করলে নতুন সব invoice আপনার BTCPay Server-এর <strong>cpay</strong> store-এ তৈরি হয়। শুরুতে এটা <strong>Off</strong> থাকে, চালু করা আপনার সিদ্ধান্ত। Off করলে নতুন invoice আবার CPAY wallet থেকে হয়, আর BTCPay-এর খোলা invoice-গুলোও settle হয়।</p>\n<h4>কীভাবে কাজ করে</h4>\n<ul><li>Payer CPAY-এর payment link-এই টাকার পরিমাণ লেখে। CPAY তখন BTCPay-তে invoice বানায়, <code>orderId</code> = <code>cpay:&lt;payment id&gt;</code>।</li><li>Store-এ যা চালু আছে সবই দেখায়: <strong>Lightning</strong> আর <strong>on-chain bitcoin</strong>। Pay পেজে Lightning QR থাকে, আর <strong>Pay with on-chain bitcoin</strong> link দিয়ে BTCPay-এর checkout পেজ খোলে।</li><li>টাকা এলে BTCPay webhook পাঠায়। CPAY signature (<code>BTCPay-Sig</code>) মিলিয়ে দেখে, তারপর BTCPay থেকে invoice আবার পড়ে নিশ্চিত হয়। একই invoice দুবার গোনা হয় না।</li><li>এরপর অন্য সব payment-এর মতোই: আগে platform fee (Admin settings-এ যা আছে, এখন ৫%), তারপর <strong>Auto withdraw</strong> On হলে বাকি টাকা user-এর address-এ যায়, Off হলে user-এর balance-এ জমা থাকে। Telegram-এ alert আসে।</li><li>BTCPay শুধু টাকা নেয়। CPAY কখনো BTCPay দিয়ে টাকা পাঠায় না। পাঠানো সব আগের মতো CPAY wallet থেকেই হয়।</li></ul>\n<h4>জরুরি কথা: on-chain টাকা</h4>\n<p><strong>On-chain bitcoin-এ দেওয়া টাকা BTCPay-এর on-chain wallet-এ জমা হয়, CPAY-এর Lightning balance-এ না।</strong> User-কে CPAY তখনই credit দেয়, আর Auto withdraw CPAY wallet থেকে পাঠায়। তাই CPAY wallet-এ সবসময় যথেষ্ট টাকা (যেমন $110) রাখুন, আর on-chain-এ জমা টাকা নিজে CPAY wallet-এ সরিয়ে নিন।</p>\n<h4>Secret (শুধু নাম, chat-এ কখনো দেবেন না)</h4>\n<ul><li><code>BTCPAY_URL</code>: আপনার BTCPay-এর ঠিকানা, <code>https://</code> দিয়ে শুরু।</li><li><code>BTCPAY_STORE_ID</code>: cpay store-এর ID (Store → Settings → General)।</li><li><code>BTCPAY_API_KEY</code>: নিচের নিয়মে বানানো API key।</li><li><code>BTCPAY_WEBHOOK_SECRET</code>: webhook-এর secret।</li></ul>\n<h4>Setup-এর ধাপ (অন্য কোনো store-এ হাত দিতে হবে না)</h4>\n<ol><li><strong>API key:</strong> BTCPay-তে Account → Manage account → <strong>API Keys</strong> → <strong>Generate key</strong>। শুধু দুটো permission টিক দিন: <strong>Create an invoice</strong> (<code>btcpay.store.cancreateinvoice</code>) আর <strong>View invoices</strong> (<code>btcpay.store.canviewinvoices</code>)। দুটোতেই শুধু <strong>cpay</strong> store বাছুন। Payout, pull payment, wallet বা অন্য কোনো permission দেবেন না।</li><li><strong>Webhook:</strong> cpay store → Settings → <strong>Webhooks</strong> → <strong>Create webhook</strong>।</li></ol>\n<p>   - Payload URL: <code>https://riumaeihemgznvgattoc.supabase.co/functions/v1/btcpay-webhook</code>    - Event: <strong>An invoice has been settled</strong>, <strong>An invoice has expired</strong>, <strong>An invoice became invalid</strong>।    - Automatic redelivery চালু রাখুন। যে secret দেখায় সেটা কপি করুন।</p>\n<ol><li><strong>Rate:</strong> cpay store → Settings → Rates-এ spread ০% রাখুন।</li><li>চারটা secret Supabase-এ Edge Function secret হিসেবে বসান।</li><li>Deploy-এর ক্রম: migration <code>20261021050000_gateway_checkout.sql</code>, তারপর <code>btcpay-webhook</code> আর <code>create-invoice</code> function, শেষে সাইট।</li><li>Admin → Settings → <strong>BTCPay Server</strong> → <strong>On</strong>। ছোট একটা Lightning আর একটা on-chain payment দিয়ে test করুন, Admin → Payments আর Telegram-এ দেখুন।</li></ol>\n<p>বিস্তারিত: <a href=\"#\">BTCPAY.md</a>।</p>\n</div>\n";
